const callStats = $('Arama İstatistikleri').first().json;
const apptStats = $('Randevu İstatistikleri').first().json;

const callCount = parseInt(callStats.call_count || 0);
const avgDuration = parseFloat(callStats.avg_duration || 0).toFixed(0);
const totalCost = parseFloat(callStats.total_cost || 0).toFixed(2);
const totalAppts = parseInt(apptStats.total || 0);
const cancelledAppts = parseInt(apptStats.cancelled || 0);
const aiBooked = parseInt(apptStats.ai_booked || 0);

const today = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
const summary = `Günlük Rapor - ${today}:\n- Toplam arama: ${callCount}\n- Ort. süre: ${avgDuration} sn\n- AI maliyeti: $${totalCost}\n- Toplam randevu: ${totalAppts}\n- İptal edilen: ${cancelledAppts}\n- AI ile alınan: ${aiBooked}`;

return [{ json: { summary, callCount, avgDuration, totalCost, totalAppts, cancelledAppts, aiBooked, today } }];
